    rst : in std_logic;
    hsync_o : out std_logic;
    vsync_o : out std_logic;
    de_o : out std_logic;
    pixel_o : out std_logic_vector(23 downto 0);
    pixel_addr_o : out unsigned(18 downto 0)
  );
end entity video_pattern_generator_top;

library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

architecture rtl of video_pattern_generator_top is

    -- VGA Timing Constants
    constant H_ACTIVE   : natural := 640;
    constant H_FRONT_PORCH : natural := 16;
    constant H_SYNC_PULSE : natural := 96;
    constant H_BACK_PORCH : natural := 48;

    constant V_ACTIVE   : natural := 480;
    constant V_FRONT_PORCH : natural := 10;
    constant V_SYNC_PULSE : natural := 2;
    constant V_BACK_PORCH : natural := 33;

    -- Horizontal and Vertical Counters
    signal h_count : unsigned(9 downto 0) := (others => '0');
    signal v_count : unsigned(9 downto 0) := (others => '0');

    -- Sync Signals
    signal hsync_i : std_logic;
    signal vsync_i : std_logic;

    -- Active Video Window Signal
    signal de_i : std_logic;

begin

    -- Horizontal Timing Counter
    process(clk, rst)
    begin
        if rising_edge(clk) then
            if rst = '1' then
                h_count <= (others => '0');
            else
                if h_count = H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE + H_BACK_PORCH - 1 then
                    h_count <= (others => '0');
                else
                    h_count <= h_count + 1;
                end if;
            end if;
        end if;
    end process;

    -- Vertical Timing Counter
    process(clk, rst)
    begin
        if rising_edge(clk) then
            if rst = '1' then
                v_count <= (others => '0');
            else
                if h_count = H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE + H_BACK_PORCH - 1 then
                    if v_count = V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE + V_BACK_PORCH - 1 then
                        v_count <= (others => '0');
                    else
                        v_count <= v_count + 1;
                    end if;
                end if;
            end if;
        end if;
    end process;

    -- Sync Generation Logic
    hsync_i <= '0' when h_count >= H_ACTIVE + H_FRONT_PORCH and h_count < H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE else '1';
    vsync_i <= '0' when v_count >= V_ACTIVE + V_FRONT_PORCH and v_count < V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE else '1';

    -- Active-Video Window Generation
    de_i <= '1' when h_count < H_ACTIVE and v_count < V_ACTIVE else '0';

    -- Pixel Addressing Path (Framebuffer-style)
    pixel_addr_o <= to_unsigned((to_integer(v_count) * H_ACTIVE) + to_integer(h_count), pixel_addr_o'length)
                    when de_i = '1' else (others => '0');

    -- Pattern Generator or Pixel Formatting Stage
    process(clk, rst)
        variable pixel_value : std_logic_vector(23 downto 0);
    begin
        if rising_edge(clk) then
            if rst = '1' then
                pixel_o <= (others => '0');
            else
                if de_i = '1' then
                    -- Simple pattern: horizontal gradient
                    pixel_value := std_logic_vector(h_count(7 downto 0)) & std_logic_vector(h_count(7 downto 0)) & std_logic_vector(h_count(7 downto 0));
                    pixel_o <= pixel_value;
                else
                    pixel_o <= (others => '0');
                end if;
            end if;
        end if;
    end process;

    -- Top-Level Video Output Integration
    hsync_o <= hsync_i;
    vsync_o <= vsync_i;
    de_o    <= de_i;

end architecture rtl;

